function moneyShort(n:number){if(n<=0)return "₹0";return n>=100000?`₹${(n/100000).toFixed(n>=1000000?0:1)}L`:`₹${Math.round(n/1000)}k`}
async function shrinkPhoto(file:File){if(!file.type.startsWith("image/"))throw new Error("Choose an image file.");if(file.size>8*1024*1024)throw new Error("Choose a photo smaller than 8 MB.");const bitmap=await createImageBitmap(file);const side=144;const canvas=document.createElement("canvas");canvas.width=side;canvas.height=side;const ctx=canvas.getContext("2d");if(!ctx)throw new Error("This browser could not prepare the photo.");const crop=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-crop)/2,(bitmap.height-crop)/2,crop,crop,0,0,side,side);bitmap.close();let quality=.62;let out=canvas.toDataURL("image/jpeg",quality);while(out.length>18000&&quality>.3){quality-=.08;out=canvas.toDataURL("image/jpeg",quality)}if(out.length>22000)throw new Error("Photo is too detailed to store safely. Choose a smaller image.");return out}
