 const [data,setData]=useState<AppData>(initialData),[section,setSection]=useState<Section>("overview"),[lang,setLang]=useState<"en"|"hi">("en"),[modal,setModal]=useState<"worker"|"wage"|"attendance"|"contract"|"equipment"|"ledger"|null>(null),[ledgerKind,setLedgerKind]=useState<AppData["ledger"][number]["kind"]>("Project expense"),[selectedWorker,setSelectedWorker]=useState(""),[selectedEquipment,setSelectedEquipment]=useState(""),[notice,setNotice]=useState(""),[query,setQuery]=useState(""),[menu,setMenu]=useState(false),[lastBackup,setLastBackup]=useState("Never"),[online,setOnline]=useState(true);
 const [auth,setAuth]=useState<"unconfigured"|"loading"|"signed-out"|"owner"|"blocked">(supabaseConfigured?"loading":"unconfigured"),[authEmail,setAuthEmail]=useState(""),[authError,setAuthError]=useState(""),[syncing,setSyncing]=useState(false),[remoteRevision,setRemoteRevision]=useState<string|null>(null),[cloudConflict,setCloudConflict]=useState<{snapshot:AppData;revision:string}|null>(null);
 const t=copy[lang];
 useEffect(()=>{setData(loadData());setOnline(navigator.onLine);setLastBackup(localStorage.getItem("lf-last-backup")||"Never");if("serviceWorker" in navigator)navigator.serviceWorker.register("/sw.js").catch(()=>{});const on=()=>setOnline(navigator.onLine);window.addEventListener("online",on);window.addEventListener("offline",on);return()=>{window.removeEventListener("online",on);window.removeEventListener("offline",on)}},[]);
 useEffect(()=>{const client=supabase;if(!client){setAuth("unconfigured");return}client.auth.getSession().then(async({data:{session}})=>{if(!session){setAuth("signed-out");return}setAuthEmail(session.user.email||"");const {data:profile}=await client.from("user_profiles").select("role").eq("user_id",session.user.id).maybeSingle();setAuth(profile?.role==="owner"?"owner":"blocked");if(profile?.role==="owner")setRemoteRevision(localStorage.getItem(`lf-cloud-revision-${session.user.id}`))});const {data:{subscription}}=client.auth.onAuthStateChange(async(_event,session)=>{if(!session){setAuth("signed-out");setAuthEmail("");return}setAuthEmail(session.user.email||"");const {data:profile}=await client.from("user_profiles").select("role").eq("user_id",session.user.id).maybeSingle();setAuth(profile?.role==="owner"?"owner":"blocked");if(profile?.role==="owner")setRemoteRevision(localStorage.getItem(`lf-cloud-revision-${session.user.id}`))});return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{if(data!==initialData) {try {localStorage.setItem(STORAGE_KEY,JSON.stringify(data));} catch{setNotice("Storage is full. Download a backup before adding more photos.")}}},[data]);
 useEffect(()=>{if(!notice)return;const id=setTimeout(()=>setNotice(""),3500);return()=>clearTimeout(id)},[notice]);
 const active=data.workers.filter(w=>w.status==="Active").length;
 const todayRows=data.attendance.filter(a=>a.date===today());
