 const receipts=month.filter(l=>l.kind==="Receipt").reduce((s,l)=>s+l.amount,0);
 const out=month.filter(l=>l.kind!=="Receipt").reduce((s,l)=>s+l.amount,0);
 const chartMonths=useMemo(()=>Array.from({length:6},(_,index)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(5-index));const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;const rows=data.ledger.filter(l=>l.date.slice(0,7)===key);return {m:d.toLocaleDateString("en-IN",{month:"short"}),a:rows.filter(l=>l.kind==="Receipt").reduce((s,l)=>s+l.amount,0),b:rows.filter(l=>l.kind!=="Receipt").reduce((s,l)=>s+l.amount,0)}}),[data.ledger]);
 const chartMax=Math.max(1,...chartMonths.flatMap(v=>[v.a,v.b]));
 const filtered=data.workers.filter(w=>`${w.name} ${w.id} ${w.phone}`.toLowerCase().includes(query.toLowerCase()));
 const save=(next:AppData)=>{const now=new Date().toISOString();const actor=authEmail||"Father (local)";const groups:[string,Array<{id:string}>,Array<{id:string}>][]=[["worker",data.workers,next.workers],["contract",data.contracts,next.contracts],["equipment",data.equipment,next.equipment],["maintenance",data.maintenance,next.maintenance],["attendance",data.attendance,next.attendance],["transaction",data.ledger,next.ledger],["wage approval",data.wageHistory,next.wageHistory]];const audit=[...(next.auditTrail||[])];for(const [type,before,after] of groups){const oldMap=new Map(before.map(item=>[item.id,JSON.stringify(item)]));for(const item of after){const old=oldMap.get(item.id);if(old!==JSON.stringify(item))audit.unshift({id:crypto.randomUUID(),actor,action:old?"updated":"added",recordType:type,recordId:item.id,occurredAt:now});oldMap.delete(item.id)}for(const id of oldMap.keys())audit.unshift({id:crypto.randomUUID(),actor,action:"updated",recordType:type,recordId:id,occurredAt:now})}setData({...next,auditTrail:audit.slice(0,5000),updatedAt:now})};
 async function backup(){try{const contents=await createBackup({...data,updatedAt:new Date().toISOString()});const blob=new Blob([contents],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`lakshmi-fabrication-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);localStorage.setItem("lf-last-backup",new Date().toLocaleString());setLastBackup(new Date().toLocaleString());setNotice("Backup created and integrity protected.")}catch(e){setNotice(e instanceof Error?`Backup failed: ${e.message}`:"Backup failed.")}}
 async function restore(file?:File){if(!file)return;try{const restored=await readBackup(await file.text());if(!window.confirm(t.confirmRestore))return;save(restored);setNotice(t.restoreSuccess)}catch(e){setNotice(e instanceof Error?`${t.restoreError}: ${e.message}`:t.restoreError)} }
 async function addWorker(f:FormData){try{const raw=String(f.get("id")||"").trim();const nextId=raw||String(Math.max(1000,...data.workers.map(w=>Number(w.id)||1000))+1);if(!/^\d{4}$/.test(nextId)||data.workers.some(w=>w.id===nextId)){setNotice("Labour ID must be unique and exactly four digits.");return}if(f.get("confirmed")!=="on"){setNotice("Father must confirm the agreed wage before saving.");return}const wageType=f.get("wageType") as "Monthly"|"Daily"|"Contract";const monthlyWage=Number(f.get("monthlyWage")||0),dailyWage=Number(f.get("dailyWage")||0),contractWage=Number(f.get("contractWage")||0);const agreed=wageType==="Monthly"?monthlyWage:wageType==="Daily"?dailyWage:contractWage;if(agreed<=0){setNotice("Enter the agreed wage amount before saving.");return}const photoFile=f.get("photo");const photo=photoFile instanceof File&&photoFile.size?await shrinkPhoto(photoFile):undefined;const w:AppData["workers"][number]={id:nextId,name:String(f.get("name")),phone:String(f.get("phone")),role:f.get("role") as "Labour"|"Mistri",status:"Active",wageType,monthlyWage,dailyWage,contractWage,photo};save({...data,workers:[w,...data.workers]});setModal(null);setNotice(t.workerAdded)}catch(e){setNotice(e instanceof Error?`Worker not saved: ${e.message}`:"Worker not saved.")}}
 function approveWage(f:FormData){const worker=data.workers.find(w=>w.id===selectedWorker);if(!worker)return;const amount=Number(f.get("amount")||0);if(amount<=0){setNotice("Enter a wage amount greater than zero.");return}if(f.get("confirmed")!=="on"){setNotice("Father must explicitly approve this wage change.");return}const wageType=f.get("wageType") as AppData["workers"][number]["wageType"];const previousAmount=worker.wageType==="Monthly"?worker.monthlyWage:worker.wageType==="Daily"?worker.dailyWage:(worker.contractWage||0);const update={...worker,wageType,monthlyWage:wageType==="Monthly"?amount:0,dailyWage:wageType==="Daily"?amount:0,contractWage:wageType==="Contract"?amount:0};const approval={id:crypto.randomUUID(),workerId:worker.id,previousType:worker.wageType,previousAmount,newType:wageType,newAmount:amount,reason:String(f.get("reason")),approvedBy:"Father",approvedAt:new Date().toISOString()};save({...data,workers:data.workers.map(w=>w.id===worker.id?update:w),wageHistory:[approval,...data.wageHistory]});setModal(null);setNotice("Father-approved wage agreement updated. Previous terms are retained in the history.")}
 function addContract(f:FormData){const c:Contract={id:`LF-${new Date().getFullYear()}-${String(Math.floor(Math.random()*900)+100)}`,company:String(f.get("company")),title:String(f.get("title")),location:String(f.get("location")),value:Number(f.get("value")),received:Number(f.get("received")||0),status:"Active",instruments:Number(f.get("instruments")||0)};save({...data,contracts:[c,...data.contracts]});setModal(null);setNotice("Contract saved.")}
 function addEquipment(f:FormData){const quantity=Math.max(1,Math.floor(Number(f.get("quantity")||1)));const contractId=String(f.get("contractId")||"")||undefined;const item={id:crypto.randomUUID(),name:String(f.get("name")),category:String(f.get("category")||"Instrument"),serialNumber:String(f.get("serialNumber")||""),quantity,condition:f.get("condition") as "Good"|"Repair"|"Retired"|"Lost",location:String(f.get("location")||""),contractId,notes:String(f.get("notes")||"")};save({...data,equipment:[item,...data.equipment],contracts:data.contracts.map(c=>c.id===contractId?{...c,instruments:c.instruments+quantity}:c)});setModal(null);setNotice("Equipment added to inventory.")}
 function addLedger(f:FormData){const item={id:crypto.randomUUID(),date:String(f.get("date")||today()),kind:ledgerKind,description:String(f.get("description")),amount:Number(f.get("amount")),contractId:String(f.get("contractId")||"")||undefined,workerId:String(f.get("workerId")||"")||undefined,equipmentId:String(f.get("equipmentId")||selectedEquipment)||undefined,approvedBy:ledgerKind==="Labour payment"||ledgerKind==="Advance"?"Father":undefined};if(item.amount<=0){setNotice("Enter an amount greater than zero.");return}if((ledgerKind==="Labour payment"||ledgerKind==="Advance")&&(!item.workerId||f.get("confirmed")!=="on")){setNotice("Select a worker and confirm the payment as Father.");return}if(ledgerKind==="Receipt"&&!item.contractId){setNotice("Choose the contract for this receipt.");return}const receiptContract=data.contracts.find(c=>c.id===item.contractId);if(ledgerKind==="Receipt"&&receiptContract&&receiptContract.received+item.amount>receiptContract.value){setNotice("Receipt exceeds remaining contract value. Confirm the contract amount first.");return}const maintenance=ledgerKind==="Equipment"&&item.equipmentId?{id:crypto.randomUUID(),equipmentId:item.equipmentId,date:item.date,description:item.description,amount:item.amount,approvedBy:"Father"}:null;const next={...data,ledger:[item,...data.ledger],maintenance:maintenance?[maintenance,...data.maintenance]:data.maintenance,contracts:ledgerKind==="Receipt"&&item.contractId?data.contracts.map(c=>c.id===item.contractId?{...c,received:c.received+item.amount}:c):data.contracts};save(next);setModal(null);setSelectedEquipment("");setNotice(maintenance?"Equipment cost and maintenance recorded.":"Transaction recorded.")}
